"""Declarative base, constraint naming convention and shared column mixins."""

from __future__ import annotations

from collections.abc import Sequence
from datetime import UTC, datetime

from sqlalchemy import DateTime, MetaData
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column
from sqlalchemy.sql import func

__all__ = ["Base", "SoftDeleteMixin", "TimestampMixin", "sql_value_list", "utcnow"]

# Without this, PostgreSQL invents names for indexes, unique constraints and
# CHECKs. An autogenerated name cannot be referenced in a migration, so
# `downgrade()` cannot drop what `upgrade()` created — the exact failure mode
# ENG-27 is verified against (`upgrade head` then `downgrade base`).
NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


def sql_value_list(values: Sequence[str]) -> str:
    """Render a Python sequence as a SQL literal list for a CHECK constraint.

    Project rule: no PostgreSQL ENUM types for evolving business values — they
    are `TEXT` plus `CHECK (col IN (...))`. This keeps the allowed values
    defined once, in Python, and stops `str(tuple)` from emitting a stray
    trailing comma for a single-element sequence.
    """
    return "(" + ", ".join(f"'{value}'" for value in values) + ")"


def utcnow() -> datetime:
    """Timezone-aware "now".

    `datetime.utcnow()` is deprecated in 3.12 and returns a *naive* datetime,
    which silently compares wrong against a `TIMESTAMPTZ` read back from
    Postgres. Ruff's DTZ rules ban it; this is the replacement.
    """
    return datetime.now(UTC)


class Base(DeclarativeBase):
    """Declarative base for every model in the application."""

    metadata = MetaData(naming_convention=NAMING_CONVENTION)


class TimestampMixin:
    """`created_at` / `updated_at`, both `TIMESTAMPTZ`.

    `DateTime(timezone=True)` with no precision argument maps to bare
    `TIMESTAMPTZ`. A precision spec silently truncates and is banned by the
    project's database rules.

    Defaults are set on both sides: `server_default` so a row inserted by a
    migration or by psql is still correct, `default` so the value is populated
    in the identity map without a round trip.
    """

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        default=utcnow,
        server_default=func.now(),
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        nullable=False,
        default=utcnow,
        onupdate=utcnow,
        server_default=func.now(),
    )


class SoftDeleteMixin:
    """`deleted_at`, `TIMESTAMPTZ` and nullable.

    GDPR erasure hard-deletes personal data; `deleted_at` marks the row that
    remains so referential integrity and audit history survive. Uniqueness on
    soft-deleted rows must therefore be enforced by a *partial* index
    (`WHERE deleted_at IS NULL`), or an erased email could never be reused.
    """

    deleted_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True),
        nullable=True,
        default=None,
    )
